import {
  getLocalSolvedPuzzleMap,
  PuzzleInfoBox,
  ClickableMonarchDevice,
} from "@hunt/puzzle-components";
import React from "react";

const CAPSTONE_SLUG = "unexplored_frontiers";

const PuzzleComponent = () => {
  const solvedPuzzles = getLocalSolvedPuzzleMap();

  return CAPSTONE_SLUG in solvedPuzzles ? (
    <div className="flex items-center gap-4">
      <p>
        You have a chance to work at Novabucks for a day. The Eland Islands
        Puzzmon are eager to try your coffee!
      </p>
      <ClickableMonarchDevice zoneSlug="eland_islands" className="w-20" />,
    </div>
  ) : (
    <PuzzleInfoBox copyable={false}>
      You need to solve the{" "}
      <a href={`/puzzles/${CAPSTONE_SLUG}`}>Eland Islands capstone puzzle</a>{" "}
      before you can access this task.
    </PuzzleInfoBox>
  );
};

export default PuzzleComponent;
